  $sections$[{"type":"header","variant":"clasico"},{"type":"hero","variant":"circular","rubroLabel":"Desde 1987 · Villa Crespo","titulo":"Masa madre y","tituloAcento":"horno a leña","descripcion":"Fermentamos la masa 48 horas y la cocinamos sobre piedra refractaria. Nada sale del horno antes de tiempo.","heroCaption":"48h","destacadoEtiqueta":"de fermento","botones":{"primary":{"funcion":"seccion","label":"Ver la carta"},"secondary":{"funcion":"seccion","label":"Mitad y mitad"}},"stats":[{"value":"48 h","label":"de fermentación"},{"value":"380°","label":"en horno a leña"},{"value":"38","label":"años en el barrio"}]},{"type":"productos","variant":"pizza","eyebrow":"La carta","titulo":"Nuestras pizzas"},{"type":"mitad-y-mitad","eyebrow":"Como en el barrio","titulo":"Mitad y mitad","descripcion":"Si no se ponen de acuerdo, no se pongan de acuerdo. Elegí un gusto para cada mitad y la mandamos así.","recargo":900},{"type":"promo-dia","eyebrow":"Todas las semanas","titulo":"Promo del día","promos":[{"id":"promo-lun","letra":"L","dia":"Lunes","titulo":"Dos muzzas al precio de una","desc":"Llevás dos pizzas de muzzarella grandes pagando una sola. Solo para retirar por el local.","precio":"$13.900","imagen":"https://images.pexels.com/photos/845811/pexels-photo-845811.jpeg?auto=compress&cs=tinysrgb&w=700&h=600&fit=crop"},{"id":"promo-mar","letra":"M","dia":"Martes","titulo":"Pizza + fainá + bebida","desc":"Cualquier pizza grande de la carta clásica, con una porción de fainá y una bebida de un litro.","precio":"$19.500","imagen":"https://images.pexels.com/photos/315755/pexels-photo-315755.jpeg?auto=compress&cs=tinysrgb&w=700&h=600&fit=crop"},{"id":"promo-mie","letra":"X","dia":"Miércoles","titulo":"Noche de masa madre","desc":"Todas las pizzas de masa madre con 25% de descuento, en el local o por delivery.","precio":"−25%","imagen":"https://images.pexels.com/photos/1146760/pexels-photo-1146760.jpeg?auto=compress&cs=tinysrgb&w=700&h=600&fit=crop"},{"id":"promo-jue","letra":"J","dia":"Jueves","titulo":"Docena de empanadas","desc":"Doce empanadas surtidas recién horneadas, con la salsa criolla de la casa incluida.","precio":"$21.900","imagen":"https://images.pexels.com/photos/1049626/pexels-photo-1049626.jpeg?auto=compress&cs=tinysrgb&w=700&h=600&fit=crop"},{"id":"promo-vie","letra":"V","dia":"Viernes","titulo":"Combo para cuatro","desc":"Dos pizzas familiares a elección, fainá para todos y dos litros de bebida.","precio":"$46.800","imagen":"https://images.pexels.com/photos/1566837/pexels-photo-1566837.jpeg?auto=compress&cs=tinysrgb&w=700&h=600&fit=crop"},{"id":"promo-sab","letra":"S","dia":"Sábado","titulo":"Pizza libre en el local","desc":"Desde las 20 hs, pizza libre a la piedra con bebida incluida. Reservá tu mesa.","precio":"$24.900","imagen":"https://images.pexels.com/photos/2147491/pexels-photo-2147491.jpeg?auto=compress&cs=tinysrgb&w=700&h=600&fit=crop"}]},{"type":"pasos","variant":"con-foto-derecha","eyebrow":"Cómo la hacemos","titulo":"Cuatro días desde la harina hasta tu mesa","descripcion":"No hay atajos: la masa necesita su tiempo y el horno su temperatura. Así trabajamos todos los días.","imagen":"https://images.pexels.com/photos/1566837/pexels-photo-1566837.jpeg?auto=compress&cs=tinysrgb&w=700&h=875&fit=crop","numeroPad":true,"pasos":[{"id":"proc-1","titulo":"Amasado","desc":"Harina de molino, agua, sal y muy poca levadura. Nada más que eso."},{"id":"proc-2","titulo":"Fermentación de 48 horas","desc":"La masa descansa en frío dos días enteros. Es lo que la hace liviana y digerible."},{"id":"proc-3","titulo":"Estirado a mano","desc":"Sin palote ni máquina, para que el borde conserve el aire de la fermentación."},{"id":"proc-4","titulo":"Horno a leña","desc":"Piedra refractaria a 380 grados. Cada pizza sale en poco más de tres minutos."}]},{"type":"contacto","variant":"delivery","bgColor":"#3f6b45","textColor":"rgba(247,241,228,0.7)","contactoTitulo":"Delivery propio","contactoTituloPrincipal":"Llegamos caliente","contactoSubtitulo":"Repartimos nosotros, sin apps de por medio. Estos son los tiempos promedio por zona.","zonasEntrega":[{"id":"zona-vc","nombre":"Villa Crespo","tiempo":"20′","costo":"Envío sin cargo"},{"id":"zona-pal","nombre":"Palermo","tiempo":"30′","costo":"Envío $1.500"},{"id":"zona-alm","nombre":"Almagro","tiempo":"35′","costo":"Envío $1.500"},{"id":"zona-cab","nombre":"Caballito","tiempo":"45′","costo":"Envío $2.200"}]},{"type":"testimonios","variant":"scroll"},{"type":"footer","variant":"minimal"}]$sections$::jsonb,
  $demo${"nombreNegocio":"La Piedra","rubroLabel":"Pizzería a la piedra, masa madre y horno a leña","sobreNosotros":"Fermentamos la masa 48 horas y la cocinamos sobre piedra refractaria en horno a leña. Sin apuro, como se hacía antes en el barrio.","whatsapp":"5491148557720","telefono":"011 4855-7720","direccion":"Serrano 890, Villa Crespo","horarios":"Mar a Dom, 19 a 00.30 hs","instagram":"@lapiedrapizzeria","galeria":["https://images.pexels.com/photos/6605214/pexels-photo-6605214.jpeg?auto=compress&cs=tinysrgb&w=1000&h=1200&fit=crop","https://images.pexels.com/photos/2762942/pexels-photo-2762942.jpeg?auto=compress&cs=tinysrgb&w=1000&h=1200&fit=crop","https://images.pexels.com/photos/1566837/pexels-photo-1566837.jpeg?auto=compress&cs=tinysrgb&w=1000&h=1200&fit=crop","https://images.pexels.com/photos/315755/pexels-photo-315755.jpeg?auto=compress&cs=tinysrgb&w=1000&h=1200&fit=crop"]}$demo$::jsonb,
